&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;[Culture Fit]&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;AI Research&amp;nbsp;본부&amp;nbsp;인원들은&amp;nbsp;다양한&amp;nbsp;프로젝트를&amp;nbsp;통하여&amp;nbsp;여러&amp;nbsp;분야의&amp;nbsp;팀원들과&amp;nbsp;교류하고&amp;nbsp;협업하며&amp;nbsp;다양한&amp;nbsp;문제에&amp;nbsp;창의적인&amp;nbsp;아이디어를&amp;nbsp;제시할&amp;nbsp;수&amp;nbsp;있습니다.&amp;nbsp;나이&amp;nbsp;및&amp;nbsp;직급에&amp;nbsp;관계없이&amp;nbsp;자유롭게&amp;nbsp;의견을&amp;nbsp;개진하는&amp;nbsp;분위기가&amp;nbsp;장려됩니다.&amp;nbsp;다양한&amp;nbsp;문화적&amp;nbsp;배경을&amp;nbsp;가진&amp;nbsp;인원들이&amp;nbsp;모여&amp;nbsp;팀을&amp;nbsp;이루고&amp;nbsp;있으며&amp;nbsp;활발한&amp;nbsp;소통을&amp;nbsp;위해&amp;nbsp;통·번역&amp;nbsp;등&amp;nbsp;언어적&amp;nbsp;장벽을&amp;nbsp;해소할&amp;nbsp;수&amp;nbsp;있는&amp;nbsp;방법들을&amp;nbsp;적극&amp;nbsp;지원하고&amp;nbsp;있습니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;우리 팀과 함께할 미션을 소개합니다.&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;크래프톤의&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;AI&amp;nbsp;연구&amp;nbsp;조직에서는&amp;nbsp;다양한&amp;nbsp;연구&amp;nbsp;주제를&amp;nbsp;기반으로&amp;nbsp;게임&amp;nbsp;및&amp;nbsp;인터랙티브&amp;nbsp;콘텐츠에&amp;nbsp;적용&amp;nbsp;가능한&amp;nbsp;AI&amp;nbsp;기술을&amp;nbsp;연구합니다. 본&amp;nbsp;포지션은&amp;nbsp;지원자분의&amp;nbsp;연구&amp;nbsp;경험과&amp;nbsp;전문성을&amp;nbsp;바탕으로,&amp;nbsp;인터뷰&amp;nbsp;과정에서&amp;nbsp;적합한&amp;nbsp;연구&amp;nbsp;조직&amp;nbsp;및&amp;nbsp;프로젝트를&amp;nbsp;함께&amp;nbsp;논의한&amp;nbsp;후&amp;nbsp;최종&amp;nbsp;팀&amp;nbsp;배정이&amp;nbsp;이루어집니다.&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;[&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Foundation Model&amp;nbsp;Research]&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;대규모&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Multimodal&amp;nbsp;LLM, World Model&amp;nbsp;학습&amp;nbsp;및&amp;nbsp;선행&amp;nbsp;연구를&amp;nbsp;진행합니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;모델 성능 향상을 위한&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Modeling&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;/&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Data /&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Evaluation&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;pipeline을&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;고도화 합니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245417&amp;quot;:false,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
