&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;[AI for Games R&amp;amp;D&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;]&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;AI Agent, Foundation Model, RL, ML&amp;nbsp;기술을&amp;nbsp;실제&amp;nbsp;게임에&amp;nbsp;적용&amp;nbsp;가능한&amp;nbsp;시스템으로&amp;nbsp;R&amp;amp;D하여&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;, 새로운 플레이 경험과 게임&amp;nbsp;제작 및 운영 혁신을 만듭니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:800,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;게임 환경과 서비스 요구사항에 맞는&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Agent&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;구조, 학습-추론-평가 방법론 및&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;End-to-End&amp;nbsp;AI&amp;nbsp;Pipeline을&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;고도화합니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:800,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;게임 프로젝트와의 긴밀한 협업을 통해 연구 성과를 프로토타입부터 실제 서비스까지&amp;nbsp;검증 및 적용하고, 재사용 가능한 핵심 기술과 플랫폼으로 확장합니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:800,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;실제 게임 환경에서 축적한 문제 정의, 기술적 통찰 및 적용 성과를 Tech&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;Report&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;, 논문, 특허, 오픈소스 등의 형태로 공유하여 기술 경쟁력을 강화합니다.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245417&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:800,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:259,&amp;quot;335559991&amp;quot;:360}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt; font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;이런 경험을 가진 분과 함께 성장하고 싶습니다! (필수요건)&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&#39;26-&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;‘&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;27&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;년도 내 전문연구요원으로 입사(현역 신규 편입) 가능하신 분 &lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;딥러닝 관련 분야 전공 석/박사 졸업 이상 혹은 이에 준하는 연구 경력&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;AI/ML&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;탑티어&amp;nbsp;학회 (&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;NeurIPS, ICLR, ICML 등)&amp;nbsp;관련&amp;nbsp;분야&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;탑티어&amp;nbsp;저널 논문 작성을 경험하신 분&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;연구를 주도할 수 있으며 딥러닝 관련 논문을 통해 빠르게 이해하고 실험 설계할 수 있는 능력&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Transformer, Diffusion 등&amp;nbsp;최신&amp;nbsp;딥러닝&amp;nbsp;모델&amp;nbsp;관련&amp;nbsp;개발&amp;nbsp;혹은&amp;nbsp;프로젝트&amp;nbsp;경험&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;새로운&amp;nbsp;domain에&amp;nbsp;빠르게 적응할 수 있는 분&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;text-decoration: underline; font-size: 10pt;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;원활한 업무 커뮤니케이션 능력&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134245417&amp;quot;:false}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
