ype":"single_select"},{"id":13601011002,"name":"Job Category - IT Infra","value":null,"value_type":"single_select"},{"id":13601012002,"name":"Job Category - Management Supporting","value":null,"value_type":"single_select"}],"id":8503503002,"updated_at":"2026-08-28T06:25:39-04:00","requisition_id":"26-33-094","title":"[Art Dept.] Technical Art (5년 이상 / 계약직)","company_name":"KRAFTON","first_published":"2026-04-17T03:31:30-04:00","language":"ko","application_deadline":null,"content":"&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;우리는 게이머의 로망을 실현하기 위해, 누구도 가지 않는 길을 갑니다.&lt;/span&gt;&lt;br&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;예상을 뛰어넘는 과감한 상상력과 기술로, 전 세계 팬들이 잊지 못할 세상을 만들기 위해 &lt;/span&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;담대하게 도전하고 개척합니다.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;We pioneer the path to players&#39; dreams.&lt;/span&gt;&lt;br&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;With bold imagination and breakthrough technology, &lt;/span&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;we create unforgettable worlds for fans across the globe.&lt;/span&gt;&lt;/p&gt;
&lt;hr&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;우리 팀(프로젝트)을 소개합니다.&amp;nbsp;&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;p class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong class=&quot;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;&lt;br&gt;Art Department 소개&lt;br&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;&lt;br&gt;Art Department는 크래프톤 게임 스튜디오의 아트 프로덕션 전반에 필요한 그래픽 기술과 솔루션을 지원하는 조직입니다. 그래픽 기술과 제작 파이프라인을 기반으로, 게임 개발팀이 빠르고 안정적으로 프로젝트를 시작하고 확장할 수 있도록 지원하며, 크래프톤만의 차별화된 아트 기술 서비스를 제공합니다&lt;br&gt;&lt;/span&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;Art Dept는 “Scale-up the Creative”와 “AI-first”라는 회사 방향성 아래, 장인정신에 기반한 높은 퀄리티, 데이터 기반 최적화, 그리고 제작 효율화를 핵심 가치로 삼고 있습니다.&lt;br&gt;&lt;/span&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;조직 구성원은 Advanced 그래픽 기술과 최신 트렌드를 선도하며, 전사 스튜디오를 대상으로 최적화된 제작 가이드라인을 제시하는 기술 파트너로서 역할을 수행합니다. 단순한 툴 지원을 넘어, 제작 과정에서 발생하는 기술적 병목을 선제적으로 해결하고, 스튜디오와의 협업(Co-development)을 통해 최상의 개발 경험을 제공합니다.&lt;br&gt;&lt;/span&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;Art Department는 경험과 신뢰를 바탕으로 국내외 다양한 스튜디오를 지원하며, 지속적으로 성과를 만들어가고 있습니다. 크래프톤 게임이 높은 그래픽 완성도를 갖추고 성공적으로 시장에 출시될 수 있도록, 함께 성장할 전문가를 기다립니다.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p id=&quot;0&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong class=&quot;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt; Visual R&amp;amp;D 팀을 소개합니다.&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;Visual R&amp;amp;D 팀은 KRAFTON Art Department 산하 조직으로, 예술적 창의성(Art)과 기술적 구현(Technology)의 시너지를 극대화하는 역할을 수행합니다. &lt;br&gt;우리는 게임 개발 과정에서 마주하는 다양한 난제를 해결하고, 크래프톤 산하 글로벌 스튜디오들이 최고의 퀄리티를 효율적으로 구현할 수 있도록 최적화된 솔루션과 제작 환경을 제공합니다.&lt;br&gt;현재 우리는 인게임 캐릭터 제작의 혁신을 목표로 하는 &#39;VCC(Visual R&amp;amp;D Character Customization)&#39; 프로젝트를 비롯하여, 차세대 그래픽 기술 연구와 개발 프로세스 고도화 업무를 주도하고 있습니다. &lt;br&gt;우리의 목표는 단순한 R&amp;amp;D를 넘어, 실제 프로젝트에 즉시 적용되어 성과를 낼 수 있는 실용적인 기준을 만드는 것입니다.&lt;br&gt;우리는 지금, 변화하는 개발 환경 속에서 유연한 사고와 협업을 통해 새로운 가치를 창출하고 프로젝트의 완성도를 높여갈 인재를 찾고 있습니다. &lt;br&gt;각 분야의 전문성을 바탕으로 크래프톤 전사 프로젝트의 성공을 함께 지원하고 성장하고 싶은 분들의 도전을 기다립니다.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h4&gt;&amp;nbsp;&lt;/h4&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;우리 팀과 함께할 미션을 소개합니다.&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li id=&quot;0&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong class=&quot;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;테크니컬 아트 문제 해결&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;
&lt;ul&gt;
&lt;li id=&quot;1&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;렌더링, 셰이더, 에셋 파이프라인 등 게임 제작 과정의 기술적 이슈를 해결한다.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;2&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;아트 에셋의 성능 영향도 분석 및 개선 방안 제시&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;3&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;셰이더 최적화 및 렌더링 파이프라인 개선&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;4&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;아티스트 워크플로우의 기술적 병목 해결&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;strong class=&quot;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;성능 기준 수립 및 가이드라인 관리&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;변화하는 디바이스 환경에 대응하여 성능 기준을 지속적으로 갱신하고 전사에 전파한다.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;플랫폼별/장르별 성능 기준 설정 및 주기적 재평가&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;최적화 노하우 및 베스트 프랙티스 문서화&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;스튜디오 대상 기술 가이드라인 배포 및 교육 지원&lt;br&gt;&lt;br&gt;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;&lt;strong class=&quot;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;스튜디오 기술 지원&lt;/span&gt;&lt;/strong&gt;&lt;/span&gt;
&lt;ul&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;국내외 자회사 스튜디오의 최적화 요청에 대응하여 직접 지원한다.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;프로젝트별 성능 진단 및 개선 방향 도출&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;필요시 스튜디오에 단기 파견되어 최적화 작업 수행&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;최적화 결과 보고서 작성 및 권고사항 제시&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;이런 경험을 가진 분과 함께 성장하고 싶습니다! (필수요건)&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li id=&quot;0&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;게임 개발 파이프라인에서의 TA 업무 경력 5년 이상&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;1&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;셰이더 작성 및 최적화 경험 (HLSL/GLSL)&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;2&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;DCC 툴(Maya, Blender 등) 및 게임 엔진 숙련도&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;3&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;스크립팅 능력(Python, MEL 등)&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;4&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;모바일/콘솔/PC 멀티플랫폼 최적화 이해&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;5&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;기술 문서 작성 및 커뮤니케이션 능력&lt;/span&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;영어 기술 자료 독해 능력&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-size: 10pt;&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;해외 출장에 결격 사유가 없는 분&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&amp;nbsp;&lt;/h4&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;이런 경험들이 있다면 저희가 찾는 그 분입니다! (우대요건)&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li id=&quot;0&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;저사양 모바일 타겟 게임 최적화 경험&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;1&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;멀티플랫폼 출시 프로젝트 참여 경험&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;2&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;라이브 서비스 게임 성능 개선 경험&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;3&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;글로벌 스튜디오와의 협업 경험&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;크래프톤의 도전에 함께 하기 위해 아래의 전형 과정이 필요합니다.&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;서류 전형 &amp;gt; *과제 전형 &amp;gt; 직무면접 (Technical Fit Interview) &amp;gt; 종합면접 (Culture Fit Interview) &amp;gt; 합격 및 입사&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;*해당 절차는 각 포지션 및 후보자에 따라 변동이 있을 수 있습니다.&lt;/span&gt;&lt;/li&gt;
