&lt;p class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&amp;nbsp;&lt;/p&gt;
&lt;p id=&quot;1&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Duties&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li id=&quot;0&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Draft, negotiate, review, and advise on a broad portfolio of commercial agreements, including:&lt;/span&gt;
&lt;ul&gt;
&lt;li id=&quot;1&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Publishing Agreements&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;2&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Platform Agreements&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;3&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Services agreements&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;4&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Development and licensing agreements&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;5&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Merchandising agreements&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;6&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Technology and software license agreements&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;7&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Data privacy–related agreements&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li id=&quot;9&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Develop, maintain, and improve contract templates, playbooks, and internal legal resources.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;10&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Draft, review, and negotiate employment-related agreements and templates.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;11&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Build strong working relationships and collaborate cross-functionally with global stakeholders.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;12&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Work closely with the IP team to identify, register, protect, and enforce the company’s IP portfolio, including copyrights, trademarks, and domain names.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Required Knowledge and Skills&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li id=&quot;0&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;5–10&lt;/span&gt;&lt;strong class=&quot;&quot;&gt; &lt;/strong&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot;&gt;years of relevant legal experience in a top-tier law firm and/or in-house legal department.&lt;/span&gt;&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;1&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;At least 3 years of hands-on experience handling commercial transactions.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;2&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Must commute to Seoul HQ Office&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;3&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Ability to independently manage commercial matters with minimal supervision.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;4&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Strong communication skills in English and ability to work effectively across time zones, cultures, and languages (including through translators).&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;5&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Team-oriented mindset; able to work both autonomously and collaboratively.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;6&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Proactive, “roll-up-your-sleeves” attitude in handling matters with or without additional support.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;7&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Hold a law degree and be licensed to practice law in the United States, or a common law jurisdiction.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;8&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Professional demeanor combined with a sense of humor.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Preferred Qualifications&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li id=&quot;0&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Korean language proficiency.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;1&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Experience with legal technology tools or platforms.&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;2&quot; class=&quot;paragraph--da25a3913a1dd210&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;Background in the video game, entertainment, or software technology industries.&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;hr&gt;
&lt;h3&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;크래프톤의 도전에 함께 하기 위해 아래의 전형 과정이 필요합니다.&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;서류 전형 &amp;gt; 인성검사 (Personality Assessment) &amp;gt; 직무면접 (Technical Fit Interview) &amp;gt; 종합면접 (2-3회) (Culture Fit Interview) &amp;gt; 학/경력 조회 &amp;gt;&amp;nbsp;합격 및 입사&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;상시채용으로 우수 인재 채용 시 조기에 마감될 수 있습니다.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;전형별 합격자에 대해 지원서에 등록하신 이메일 혹은 유선으로 개별 안내 드립니다.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;전화 인터뷰의 경우, 필수 전형이 아닌 필요에 따라 진행되는 선택 전형임을 사전 안내 드립니다. 이에 대한 상세 내용은 개별 안내 드립니다.&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;필요 시 면접은 추가될 수 있으며, 이에 대한 상세 내용은 개별 안내 드립니다.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;&amp;nbsp;&lt;/h4&gt;
&lt;h3 id=&quot;JobPostSetting-필요서류를확인해주세요!-제출서류/포트폴리오(필수및선택서류꼭확인!)&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;필요 서류를 확인해주세요!&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span style=&quot;font-size: 10pt;&quot;&gt;입사지원서 (자유 양식), 경력기술서, 자기소개서&lt;/span&gt;&lt;/li&gt;
