&lt;li id=&quot;2&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;글로벌/국내 게임 서비스 심의 및 등급 분류 지원&lt;/span&gt;&lt;/li&gt;
&lt;li id=&quot;3&quot; class=&quot;paragraph--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot; data-paragraph=&quot;true&quot; data-type=&quot;p&quot;&gt;&lt;span class=&quot;text--da25a3913a1dd210&quot; style=&quot;font-size: 10pt;&quot;&gt;글로벌/국내 게임 서비스 정책 준수 여부 점검&lt;/span&gt;&lt;/li&gt;
