&lt;/li&gt;
&lt;li data-local-id=&quot;c827a1cf-2f3f-4ef5-8d39-387d75042845&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
