&lt;p data-local-id=&quot;777dcb84ea26&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;paragraph&quot; data-prosemirror-node-block=&quot;true&quot;&gt;&lt;strong data-prosemirror-content-type=&quot;mark&quot; data-prosemirror-mark-name=&quot;strong&quot;&gt;Customer-centric:&lt;/strong&gt; You are driven to understand customer challenges and needs, crafting solutions that provide real value.&lt;/p&gt;
&lt;/li&gt;
&lt;li data-local-id=&quot;06f0539d-7772-43c5-b8b9-4d2a1b837413&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
