&lt;/li&gt;
&lt;li data-local-id=&quot;6fe88bd6-6a91-4f59-9e92-8a487cc5096b&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
