&lt;/li&gt;
&lt;li data-local-id=&quot;2a2d3704-7db1-45b0-9ea9-cb8f62f5d315&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
