&lt;li data-local-id=&quot;a7f67047-0008-4b54-a1a9-977bcbbe14b4&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
