&lt;ul class=&quot;ak-ul&quot; data-local-id=&quot;a2b7ac1f-2545-4c55-b24f-94fffaec6ff4&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;bulletList&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
