&lt;/li&gt;
&lt;li data-local-id=&quot;c36ce839-2d87-4709-bfe0-b1f90a7e3096&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
