&lt;/li&gt;
&lt;li data-local-id=&quot;a0af51cb-7738-4804-9e57-f8c829121190&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
