&lt;/li&gt;
&lt;li data-local-id=&quot;65227e3c-69ca-4f35-b39d-4b7d6421fab8&quot; data-prosemirror-content-type=&quot;node&quot; data-prosemirror-node-name=&quot;listItem&quot; data-prosemirror-node-block=&quot;true&quot;&gt;
